(function($){'use strict';let initialData='';let formDirty=!1;function syncDirty(){const $form=$('.shp4cf7-admin form');if(!$form.length){return''}
return $form.serialize()}
function validateRules(value){const lines=value.split(/\r?\n/);const errors=[];$.each(lines,function(i,line){line=$.trim(line);if(''===line||0===line.indexOf('#')){return}
let typed=line;if(''===typed){return}
let isEmail=!1;let isIp=!1;if(typed.indexOf('@')!==-1){isEmail=!0}else if(/^[\d\*][\d.\*\/]+$/.test(typed)&&typed.indexOf('.')!==-1){isIp=!0}else if(/^[0-9a-fA-F:\*\/]+$/.test(typed)&&(typed.split(':').length-1)>=2){isIp=!0}
if(!isEmail&&!isIp){errors.push(line)}});return errors}
function showFieldError($field,message){let $err=$field.siblings('.shp4cf7-field-error');if(!$err.length){$err=$('<p class="shp4cf7-field-error"></p>');$field.after($err)}
$err.text(message).addClass('is-visible');$field.addClass('shp4cf7-field-invalid')}
function clearFieldError($field){$field.closest('td').find('.shp4cf7-field-error').removeClass('is-visible');$field.removeClass('shp4cf7-field-invalid')}
$(function(){let $pendingTrigger=null;let $confirmDialog=null;let countdownTimer=null;function getConfirmDialog(){if($confirmDialog){return $confirmDialog}
$confirmDialog=$('<dialog class="shp4cf7-dialog">'+'<div class="shp4cf7-dialog-inner">'+'<div class="shp4cf7-confirm-header">'+'<span class="dashicons dashicons-warning"></span>'+'<strong>'+simpleHoneypotCf7.confirmTitle+'</strong>'+'</div>'+'<p class="shp4cf7-confirm-message"></p>'+'<div class="shp4cf7-dialog-actions">'+'<button type="button" class="button button-primary shp4cf7-confirm-yes" disabled>'+simpleHoneypotCf7.confirmYes+'</button>'+'<button type="button" class="button shp4cf7-confirm-no">'+simpleHoneypotCf7.confirmNo+'</button>'+'</div>'+'</div>'+'</dialog>');$('body').append($confirmDialog);return $confirmDialog}
function openConfirmDialog($trigger){const $dialog=getConfirmDialog();const isDanger=$trigger.data('confirm-danger')!==undefined;const $header=$dialog.find('.shp4cf7-confirm-header');const $yes=$dialog.find('.shp4cf7-confirm-yes');let message=$trigger.data('confirm');const daysInput=$trigger.data('confirm-days');if(daysInput){const daysValue=$('#'+daysInput).val()||'90';message=message.replace('%d',daysValue);$dialog.find('.shp4cf7-confirm-message').html(message)}else{$dialog.find('.shp4cf7-confirm-message').text(message)}
if(isDanger){$header.show();$yes.prop('disabled',!0);startCountdown($yes,3)}else{$header.hide();$yes.prop('disabled',!1)}
$pendingTrigger=$trigger;$dialog[0].showModal()}
function startCountdown($button,seconds){let remaining=seconds;clearInterval(countdownTimer);$button.text(simpleHoneypotCf7.confirmYes+' ('+remaining+'s)');countdownTimer=setInterval(function(){remaining--;if(remaining<=0){clearInterval(countdownTimer);$button.text(simpleHoneypotCf7.confirmYes).prop('disabled',!1)}else{$button.text(simpleHoneypotCf7.confirmYes+' ('+remaining+'s)')}},1000)}
function closeConfirmDialog(){const $dialog=getConfirmDialog();$dialog[0].close();clearInterval(countdownTimer);$pendingTrigger=null}
$(document).on('click','[data-confirm]',function(e){e.preventDefault();openConfirmDialog($(this))});$(document).on('click','.shp4cf7-confirm-yes',function(){if($(this).prop('disabled')||!$pendingTrigger){return}
const action=$pendingTrigger.data('action');if(action){const payload={action:action};if('purge_events'===action){payload.days=parseInt($('#shp4cf7_purge_days').val(),10)||90}
closeConfirmDialog();const actionMap={'reset_stats':'stats-reset','reset_settings':'settings-reset','purge_events':'purge-events','force_update_check':'update-check-cleared'};const redirectKey=actionMap[action]||action;$.ajax({url:simpleHoneypotCf7.restUrl,method:'POST',contentType:'application/json',beforeSend:function(xhr){xhr.setRequestHeader('X-WP-Nonce',simpleHoneypotCf7.restNonce)},data:JSON.stringify(payload),dataType:'json'}).done(function(){window.location.href=simpleHoneypotCf7.tabUrl+'&updated='+redirectKey}).fail(function(){window.location.href=simpleHoneypotCf7.tabUrl+'&updated=action-failed'})}else if($pendingTrigger.attr('href')){const href=$pendingTrigger.attr('href');closeConfirmDialog();window.location.href=href}else{closeConfirmDialog()}});$(document).on('click','.shp4cf7-confirm-no',function(){closeConfirmDialog()});const $form=$('.shp4cf7-admin form');if(!$form.length){return}
$(document).on('focus','.insert-box input.tag.code',function(){$(this).select()});initialData=syncDirty();$form.on('change input','input, select, textarea',function(){formDirty=syncDirty()!==initialData});$form.on('input change','input[type="number"], input[type="text"], textarea',function(){clearFieldError($(this))});$form.on('submit',function(e){let valid=!0;const $submitter=$(document.activeElement);const isImport=$submitter.is('#shp4cf7-import-btn');if(isImport&&(!$importFile.length||!$importFile[0].files.length)){showFieldError($importFile.next('label'),simpleHoneypotCf7.selectFile);valid=!1}
$form.find('input[type="number"]').each(function(){const $input=$(this);const val=$input.val();if(''===val){return}
const num=parseInt(val,10);const min=$input.attr('min');const max=$input.attr('max');const label=$input.closest('tr').find('label').text();if(min!==undefined&&num<parseInt(min,10)){showFieldError($input,label+': '+simpleHoneypotCf7.valueTooLow.replace('%s',min));valid=!1}else if(max!==undefined&&num>parseInt(max,10)){showFieldError($input,label+': '+simpleHoneypotCf7.valueTooHigh.replace('%s',max));valid=!1}});const $rules=$form.find('.shp4cf7-rules');if($rules.length&&!$rules.prop('disabled')){const errors=validateRules($rules.val());if(errors.length){showFieldError($rules,simpleHoneypotCf7.invalidRules.replace('%s',errors.join(', ')));valid=!1}}
if(!valid){e.preventDefault();formDirty=!1}else{formDirty=!1;if($submitter.is('input[type="submit"], button[type="submit"]')&&!isImport){$submitter.prop('disabled',!0)}}});$form.on('change','.shp4cf7-custom-rules-toggle input',function(){const $ta=$(this).closest('.shp4cf7-custom-rules-group').find('.shp4cf7-rules');$ta.prop('disabled',!this.checked).toggleClass('shp4cf7-rules-disabled',!this.checked)});$form.find('.shp4cf7-custom-rules-toggle input:not(:checked)').trigger('change');const $importFile=$('#shp4cf7-import-file');const $importBtn=$('#shp4cf7-import-btn');const $importLabel=$importFile.next('label');const importDefaultText=$importLabel.text();if($importFile.length&&$importBtn.length){$importFile.on('change',function(){const hasFile=this.files.length>0;$importBtn.prop('disabled',!hasFile);$importLabel.text(hasFile?this.files[0].name:importDefaultText);$importLabel.attr('title',hasFile?this.files[0].name:'');clearFieldError($importFile)})}});$(window).on('beforeunload',function(){if(formDirty){return simpleHoneypotCf7.unsavedChanges}})}(jQuery))